#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

enum { BUCKETS = 1024, MAX_WORDS = 3000 };

typedef struct Entry {
    char key[31];
    int count;
    struct Entry *next;
} Entry;

static Entry *table[BUCKETS];
static Entry *order[MAX_WORDS];

static uint32_t fnv1a(const char *s) {
    uint32_t h = 2166136261u;
    for (; *s != '\0'; s++) {
        h ^= (unsigned char)*s;
        h *= 16777619u;
    }
    return h;
}

int main(void) {
    char word[31];
    int distinct = 0;
    while (scanf("%30s", word) == 1) {
        uint32_t b = fnv1a(word) % BUCKETS;
        Entry *e = table[b];
        while (e != NULL && strcmp(e->key, word) != 0) {
            e = e->next;
        }
        if (e == NULL) {
            if (distinct == MAX_WORDS) {
                break;
            }
            e = malloc(sizeof *e);
            if (e == NULL) {
                return 1;
            }
            strcpy(e->key, word);
            e->count = 0;
            e->next = table[b];
            table[b] = e;
            order[distinct++] = e;
        }
        e->count++;
    }
    for (int i = 0; i < distinct; i++) {
        printf("%s %d\n", order[i]->key, order[i]->count);
    }
    for (int i = 0; i < distinct; i++) {
        free(order[i]);
    }
    return 0;
}

additionalExercises.description:
Реализуйте множество целых чисел на хеш-таблице с открытой адресацией и линейным пробированием и выполните команды:

- `add x` — добавить `x` (если уже есть — ничего не делать);
- `del x` — удалить `x` (если нет — ничего не делать);
- `has x` — напечатать `да` или `нет`.

В конце напечатайте `размер: N` — число элементов множества. Удаление должно оставлять надгробие, чтобы не ломать поиск.

