#include <stdint.h>
#include <stdio.h>
#include <string.h>

enum { M = 4096, EMPTY = 0, USED = 1, TOMB = 2 };

static int keys[M];
static unsigned char state[M];

static uint32_t slot(int x) {
    return ((uint32_t)x * 2654435761u) >> 20;
}

// Индекс ячейки с ключом x или −1.
static int find(int x) {
    for (uint32_t i = slot(x), step = 0; step < M; i = (i + 1) % M, step++) {
        if (state[i] == EMPTY) {
            return -1;
        }
        if (state[i] == USED && keys[i] == x) {
            return (int)i;
        }
    }
    return -1;
}

int main(void) {
    int size = 0;
    char command[8];
    int x;
    while (scanf("%7s %d", command, &x) == 2) {
        int at = find(x);
        if (strcmp(command, "has") == 0) {
            printf("%s\n", at >= 0 ? "да" : "нет");
        } else if (strcmp(command, "del") == 0) {
            if (at >= 0) {
                state[at] = TOMB;
                size--;
            }
        } else if (strcmp(command, "add") == 0 && at < 0) {
            uint32_t i = slot(x);
            while (state[i] == USED) {
                i = (i + 1) % M;
            }
            keys[i] = x;
            state[i] = USED;
            size++;
        }
    }
    printf("размер: %d\n", size);
    return 0;
}

