#include <stdint.h>
#include <stdio.h>

enum { BITS = 18, M = 1 << BITS };

static long long keys[M];
static int counts[M];
static bool used[M];

static uint32_t slot(long long key) {
    return (uint32_t)(((uint64_t)key * 0x9E3779B97F4A7C15ull) >> (64 - BITS));
}

// Ячейка ключа: либо с этим ключом, либо пустая, куда его можно положить.
static uint32_t locate(long long key) {
    uint32_t i = slot(key);
    while (used[i] && keys[i] != key) {
        i = (i + 1) & (M - 1);
    }
    return i;
}

int main(void) {
    int n;
    long long target;
    if (scanf("%d %lld", &n, &target) != 2 || n < 1 || n > 100000) {
        return 0;
    }
    long long pairs = 0;
    for (int k = 0; k < n; k++) {
        long long x;
        if (scanf("%lld", &x) != 1) {
            break;
        }
        uint32_t need = locate(target - x);
        if (used[need]) {
            pairs += counts[need];
        }
        uint32_t at = locate(x);
        if (!used[at]) {
            used[at] = true;
            keys[at] = x;
        }
        counts[at]++;
    }
    printf("%lld\n", pairs);
    return 0;
}

